# 缓存行为观察实验
# 
# 实验观察三种典型的缓存行为：
# 1. 首次访问缺失，后续访问命中（相同地址重复访问）
# 2. 冲突缺失（不同地址映射到相同缓存组）
# 3. 缓存抖动（反复访问冲突地址，导致持续缺失）

.section .text
.globl _start

_start:
    # 设置：初始化寄存器，选择映射到相同缓存组的地址
    li x5, 0x2000      # 地址A: 0x2000
    li x6, 0x3000      # 地址B: 0x3000（与A映射到相同缓存组）

    # 设置：在两个地址存储不同的数据模式
    li x7, 0xdeadbeef
    sw x7, 0(x5)       # 在地址A存储数据
    li x7, 0xcafebabe
    sw x7, 0(x6)       # 在地址B存储数据

    # 模式1：首次缺失后连续命中
    lw x7, 0(x5)       # 首次访问A（缺失）
    lw x7, 0(x5)       # 再次访问A（命中）
    lw x7, 0(x5)       # 第三次访问A（命中）

    # 模式2：冲突缺失
    lw x7, 0(x5)       # 访问A（应该命中，因为前面已加载）
    lw x7, 0(x6)       # 访问B（缺失，会替换A的数据）
    lw x7, 0(x5)       # 再次访问A（缺失，会替换B的数据）
    lw x7, 0(x6)       # 再次访问B（缺失，会替换A的数据）

    # 模式3：缓存抖动循环
    li x28, 3          # 循环计数器
    loop:
        lw x7, 0(x5)   # 从A加载（除第一次外均为缺失）
        lw x7, 0(x6)   # 从B加载（缺失，替换A的数据）
        addi x28, x28, -1
        bnez x28, loop

    li      a0, 1
    csrw    mtohost, a0

infinite:
    j       infinite
